def velocities(label):
    return np.array(
        [float(row[VALUE_COL]) for row in rows if row[GROUP_COL] == label],
        dtype=float,
    )

ids = [row[UNIT_COL] for row in rows]
if len(set(ids)) != len(ids):
    raise ValueError("landform_id must be unique: one row per landform")
